vector<long> tree, lazy;
int n;

void pushDown(int node, int l, int r) {
    if (lazy[node] == 0) return;
    int mid = (l + r) / 2;
    int leftSize = mid - l + 1, rightSize = r - mid;
    tree[2*node+1] += lazy[node] * leftSize;
    tree[2*node+2] += lazy[node] * rightSize;
    lazy[2*node+1] += lazy[node];
    lazy[2*node+2] += lazy[node];
    lazy[node] = 0;
}

void rangeUpdate(int node, int l, int r, int ql, int qr, int delta) {
    if (qr < l || r < ql) return;                    // completely outside
    if (ql <= l && r <= qr) {                          // completely inside
        tree[node] += (long)delta * (r - l + 1);
        lazy[node] += delta;
        return;
    }
    pushDown(node, l, r);
    int mid = (l + r) / 2;
    rangeUpdate(2*node+1, l, mid, ql, qr, delta);
    rangeUpdate(2*node+2, mid+1, r, ql, qr, delta);
    tree[node] = tree[2*node+1] + tree[2*node+2];
}

long rangeQuery(int node, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return 0;
    if (ql <= l && r <= qr) return tree[node];
    pushDown(node, l, r);
    int mid = (l + r) / 2;
    return rangeQuery(2*node+1, l, mid, ql, qr) + rangeQuery(2*node+2, mid+1, r, ql, qr);
}
